					"type": "string",
					"minLength": 1
				},
				"excluded": {
					"type": "array",
					"items": { "type": "string", "minLength": 1 }
				}
			}
		},
		"hard_constraints": {
			"type": "array",
			"items": { "type": "string", "minLength": 1 }
		},
